    Bug 1988837 - Use the exception dialog when overriding a bad certificate from within account settings. r=darktrojan

    Differential Revision: https://phabricator.services.mozilla.com/D266316

diff --git a/mail/test/browser/account/browser_certificateCheck.js b/mail/test/browser/account/browser_certificateCheck.js
index e69dfc2c092..de50bd7e743 100644
--- a/mail/test/browser/account/browser_certificateCheck.js
+++ b/mail/test/browser/account/browser_certificateCheck.js
@@ -719,11 +719,16 @@ async function fetchCert(
  * @param {nsIX509Cert} certificate - The certificate to test.
  */
 async function addException(certCheck, certificate) {
+  const dialogPromise = BrowserTestUtils.promiseAlertDialog(
+    "extra1",
+    "chrome://pippki/content/exceptionDialog.xhtml"
+  );
   EventUtils.synthesizeMouseAtCenter(
     certCheck.addExceptionButton,
     {},
     certCheck.ownerGlobal
   );
+  await dialogPromise;

   const isTemporary = {};
   Assert.ok(
diff --git a/mailnews/base/prefs/content/certificate-check.mjs b/mailnews/base/prefs/content/certificate-check.mjs
index f634b3310c7..60ef099286b 100644
--- a/mailnews/base/prefs/content/certificate-check.mjs
+++ b/mailnews/base/prefs/content/certificate-check.mjs
@@ -389,27 +389,49 @@ class CertificateCheck extends HTMLElement {
    * Add an exception for the certificate.
    */
   #addException() {
-    certOverrideService.rememberValidityOverride(
-      this.hostname,
-      this.port,
-      {},
-      this.#certificate,
-      !Services.prefs.getBoolPref("security.certerrors.permanentOverride", true)
-    );
-    Glean.mail.certificateExceptionAdded.record({
-      error_category: this.#securityInfo.errorCodeString,
-      protocol: this.type,
-      port: this.port,
-      ui: "certificate-check",
-    });
+    const params = {
+      exceptionAdded: false,
+      securityInfo: this.#securityInfo,
+      prefetchCert: true,
+      location: this.hostname + ":" + this.port,
+    };
+    const dialog = Services.wm
+      .getMostRecentWindow("")
+      .openDialog(
+        "chrome://pippki/content/exceptionDialog.xhtml",
+        "",
+        "chrome,centerscreen,dependent",
+        params
+      );
+    const onWindowClosed = win => {
+      if (win == dialog.opener) {
+        // Avoid leaking if this window closes before the exception dialog.
+        dialog.close();
+        return;
+      } else if (win != dialog) {
+        return;
+      }
+      Services.obs.removeObserver(onWindowClosed, "domwindowclosed");
+      if (!params.exceptionAdded) {
+        return;
+      }

-    document.l10n.setAttributes(
-      this.statusLabel,
-      "certificate-check-exception-added"
-    );
-    this.addExceptionButton.hidden = true;
-    this.removeExceptionButton.hidden = false;
-    this.#hasException = true;
+      document.l10n.setAttributes(
+        this.statusLabel,
+        "certificate-check-exception-added"
+      );
+      this.addExceptionButton.hidden = true;
+      this.removeExceptionButton.hidden = false;
+      this.#hasException = true;
+
+      Glean.mail.certificateExceptionAdded.record({
+        error_category: this.#securityInfo.errorCodeString,
+        protocol: this.type,
+        port: this.port,
+        ui: "certificate-check",
+      });
+    };
+    Services.obs.addObserver(onWindowClosed, "domwindowclosed");
   }

